mapper.select:
SELECT COUNT(*)
  FROM tdm09_appr_step
 WHERE tdm09_company_id = #{companyId}
   AND tdm09_type_cd    = 'T'
   AND tdm09_parent_id  = #{apprStepId}

mapper.update:
UPDATE tdm09_appr_step
   SET tdm09_role_id  = #{row.roleId}
     , tdm09_org_id   = #{row.orgId}
     , tdm09_upd_nm   = #{updName}
     , tdm09_upd_date = f_sysdate()
 WHERE tdm09_appr_step_id = #{row.apprStepId}

UPDATE tdm09_appr_step
   SET tdm09_role_id = #{roleId}
     , tdm09_org_id  = #{orgId}
 WHERE tdm09_parent_id = #{apprStepId}
   AND tdm09_type_cd   = 'T'

UPDATE tdm09_appr_step
   SET tdm09_appr_seq = #{apprSeq}
     , tdm09_upd_nm   = #{updName}
     , tdm09_upd_date = f_sysdate()
 WHERE tdm09_appr_step_id = #{apprStepId}

mapper.delete:
DELETE FROM tdm09_appr_step
 WHERE tdm09_company_id = #{companyId}
   AND tdm09_appr_step_id IN
#{id}
